// Generated by Cypress Author on 2026-10-22
//
// USU 01 · USU 02 (UI) — Plano_de_Testes_QA_MatchWallet.md §4 (docs-test/areas/usu.md).
// A listagem pede sempre `pageSize=100` e a busca vai ao servidor (debounce de 300 ms). A regra de
// filtro e a paginação de verdade são do servidor (ver `real/usuarios-servidor`).
//
// Falham até correção (cada um marcado no título):
//  - paginação: a tela não tem Anterior/Próxima; com mais de 100 usuários o resto some em silêncio;
//  - busca: ao buscar, a página mostra "Carregando…", desmonta a tabela e o campo volta VAZIO — o
//    termo some, o vazio não cita o termo e "limpar" não refaz a lista;
//  - espaços nas bordas do termo vão ao servidor, que não os apara.

interface UsuarioStub {
  id: string
  nome: string
  email: string
  perfil: 'cliente' | 'admin'
  ativo: boolean
  criadoEm: string
}

const ANA: UsuarioStub = {
  id: 'u-ana',
  nome: 'Ana Cliente',
  email: 'ana@teste.com',
  perfil: 'cliente',
  ativo: true,
  criadoEm: '2026-01-10T00:00:00.000Z',
}
const JOSE: UsuarioStub = {
  id: 'u-jose',
  nome: 'José Ândré',
  email: 'jose.andre@teste.com',
  perfil: 'cliente',
  ativo: false,
  criadoEm: '2026-02-20T00:00:00.000Z',
}
const ROOT: UsuarioStub = {
  id: 'u-root',
  nome: 'Admin Raiz',
  email: 'raiz@teste.com',
  perfil: 'admin',
  ativo: true,
  criadoEm: '2026-03-30T00:00:00.000Z',
}
const TODOS = [ANA, JOSE, ROOT]

/** Filtro igual ao do servidor: contém, sem diferenciar caixa, em nome ou e-mail. */
function filtrar(termo: string | undefined) {
  if (!termo) return TODOS
  const t = termo.toLowerCase()
  return TODOS.filter((u) => u.nome.toLowerCase().includes(t) || u.email.toLowerCase().includes(t))
}

function prepararLista() {
  cy.bloquearApi()
  cy.stubSessao('admin')
  cy.stubApi('GET', '/usuarios/*/historico-suitability', [], 'historico')
  cy.intercept({ method: 'GET', pathname: '/api/v1/usuarios' }, (req) => {
    const itens = filtrar(req.query.search as string | undefined)
    req.reply({ items: itens, total: itens.length, page: 1, pageSize: 100 })
  }).as('usuarios')
}

function buscar(termo: string) {
  cy.get('[data-cy="usuarios-busca"]').clear().type(termo)
  return cy.wait('@usuarios')
}

describe('Plano QA · Usuários · listagem (USU 01)', () => {
  beforeEach(() => {
    prepararLista()
  })

  it('USU 01 · abre a listagem → colunas e dados de cada usuário e seleção abre o usuário correspondente', () => {
    cy.visit('/admin/usuarios')
    cy.wait('@usuarios').its('request.query').should('include', { pageSize: '100' })

    for (const coluna of ['Usuário', 'Papel', 'Status', 'Desde']) {
      cy.contains('th', coluna).should('be.visible')
    }
    cy.get('[data-cy="usuario-linha"]').should('have.length', 3)
    cy.contains('tr', 'Ana Cliente')
      .should('contain.text', 'ana@teste.com')
      .and('contain.text', 'Cliente')
      .and('contain.text', 'Ativo')
      .and('contain.text', '10/01/2026')
    cy.contains('tr', 'José Ândré')
      .should('contain.text', 'Cliente')
      .and('contain.text', 'Inativo')
      .and('contain.text', '20/02/2026')
    cy.contains('tr', 'Admin Raiz')
      .should('contain.text', 'Admin')
      .and('contain.text', 'Ativo')
      .and('contain.text', '30/03/2026')
    // Senha/hash nunca aparecem na listagem.
    cy.contains(/senha|hash/i).should('not.exist')

    // Cada linha abre o seu próprio usuário.
    for (const usuario of TODOS) {
      cy.contains('[data-cy="usuario-linha"]', usuario.nome).click()
      cy.get('[role="dialog"]').within(() => {
        cy.contains(usuario.nome).should('be.visible')
        cy.contains(usuario.email).should('be.visible')
        cy.contains('dd', usuario.ativo ? 'Ativo' : 'Inativo').should('be.visible')
      })
      cy.get('[aria-label="Fechar cadastro"]').click()
      cy.get('[role="dialog"]').should('not.exist')
    }
  })

  // ATENÇÃO — deve FALHAR: sem controles de página, 150 usuários viram só os 100 primeiros.
  it('USU 01 · total maior que a página (150 usuários, 100 exibidos) → há como chegar aos demais (falha até existir paginação)', () => {
    cy.intercept({ method: 'GET', pathname: '/api/v1/usuarios' }, (req) => {
      const itens = Array.from({ length: 100 }, (_, i) => ({
        ...ANA,
        id: `u-${i}`,
        nome: `Usuário ${i}`,
      }))
      req.reply({ items: itens, total: 150, page: 1, pageSize: 100 })
    }).as('usuarios')

    cy.visit('/admin/usuarios')
    cy.wait('@usuarios')
    cy.get('[data-cy="usuario-linha"]').should('have.length', 100)

    cy.contains('button, a', /próxima/i).should('be.visible')
    cy.contains('button, a', /anterior/i).should('be.visible')
  })
})

describe('Plano QA · Usuários · busca (USU 02)', () => {
  beforeEach(() => {
    prepararLista()
    cy.visit('/admin/usuarios')
    cy.wait('@usuarios')
  })

  it('USU 02 · nome completo, trecho, e-mail, caixa diferente e termo inexistente → envia o termo ao servidor e mostra só o que casa', () => {
    const casos: Array<{ termo: string; esperados: UsuarioStub[] }> = [
      { termo: 'Ana Cliente', esperados: [ANA] },
      { termo: 'cliente', esperados: [ANA] },
      { termo: 'jose.andre@teste.com', esperados: [JOSE] },
      { termo: 'RAIZ', esperados: [ROOT] },
      { termo: 'José', esperados: [JOSE] },
      { termo: '@teste.com', esperados: TODOS },
    ]
    for (const { termo, esperados } of casos) {
      buscar(termo).its('request.query.search').should('eq', termo)
      cy.get('[data-cy="usuario-linha"]').should('have.length', esperados.length)
      for (const u of esperados)
        cy.contains('[data-cy="usuario-linha"]', u.nome).should('be.visible')
    }

    // Termo sem resultado: estado vazio claro, sem linhas.
    buscar('zzz-inexistente')
    cy.contains('Nenhum usuário encontrado').should('be.visible')
    cy.get('[data-cy="usuario-linha"]').should('not.exist')
  })

  // ATENÇÃO — deve FALHAR: `Tabela.vue` é desmontada durante o "Carregando…" e o `search` local zera.
  it('USU 02 · depois de buscar → o termo continua no campo, o vazio cita o termo e limpar devolve a lista inteira (falha até manter o campo)', () => {
    buscar('zzz')
    cy.get('[data-cy="usuarios-busca"]').should('have.value', 'zzz')
    cy.contains('Nenhum usuário encontrado para "zzz".').should('be.visible')

    cy.get('[data-cy="usuarios-busca"]').clear()
    cy.wait('@usuarios')
    cy.get('[data-cy="usuario-linha"]').should('have.length', 3)
  })

  // ATENÇÃO — deve FALHAR: o termo vai cru; "  ana  " não casa nada no servidor.
  it('USU 02 · espaços nas bordas do termo → ignorados na busca (falha até aparar o termo)', () => {
    buscar('  ana  ').its('request.query.search').should('eq', 'ana')
    cy.contains('[data-cy="usuario-linha"]', 'Ana Cliente').should('be.visible')
  })
})

export {}
